style.css:
@-moz-document domain("roblox.com") {
/* Profile Page Styles */
/* Profile Header and Avatar Background */
.section-content.profile-header-content.ng-scope, 
.rbx-tabs-horizontal .nav-tabs *, 
.profile-avatar-mask, 
.section.layer.profile-collections.ng-scope, 
.switcher *, 
.section.profile-statistics .section-content {
    background-color: #ffe6e6 !important;
}

.section-content.profile-header-content.ng-scope *, 
.rbx-tabs-horizontal .nav-tabs *, 
.profile-container .asset-item, 
.switcher *, 
.section.profile-statistics .section-content *, 
.profile-about * {
    color: #a88b7e !important;
}

/* Avatar Viewer */
.profile-avatar-left {
    background: transparent !important;
}

/* Catalog Page Styles */
/* Creator Text */
.creator-name.text-link, 
.text-robux-tile {
    color: black !important;
}

/* Topics */
.topic.ng-binding.ng-scope {
    background-color: #fcdcdc !important;
    color: #edbebe !important;
}

/* Catalog Filters and Dropdown */
.search-options.ng-scope *, 
.text-link.breadcrumb-link.ng-binding {
    color: black !important;
}

.input-dropdown-btn.category-options.ng-scope {
    color: white !important;
    background-color: #f7d0e0 !important;
}

/* Catalog Searchbar */
.catalog-container .search-container .input-group .search-input, 
.catalog-container .search-container .input-group .autocomplete-dropdown-menu .dropdown-menu {
    background-color: #ffe6e7 !important;
    border-color: #d1a7a7 !important;
    border-radius: 5px !important;
    color: white !important;
}

/* Game Page Styles */
/* Voting/Favorite/Follow Panel */
.favorite-follow-vote-share * {
    color: white !important;
}

/* Game Description */
.text.game-description.linkify, 
.age-rating-details.col-xs-12.section-content *, 
.age-recommendation-title {
    color: #a68d7e !important;
    font-weight: 400 !important;
}

/* Game Stats */
.border-top.border-bottom.game-stats-container.follow-button-enabled, 
.age-rating-details {
    background-color: #fcdcdc !important;
}

.border-top.border-bottom.game-stats-container.follow-button-enabled * {
    color: #a6897e !important;
    font-weight: 500 !important;
}

/* Settings Page Styles */
/* Sidebar Menu */
#vertical-menu {
    background-color: #f7d0d0 !important;
}

#vertical-menu * {
    color: #a68b7e !important;
}

/* Text and Boxes */
.text-label.account-settings-label, 
.text-label.label-desktop.ng-binding, 
#settings-container .rbx-tab-content * {
    color: #fcdede !important;
}

#security-page-description, 
.section-content.notifications-section, 
.section-content.settings-security-setting-container, 
.section-content.content-controls-section {
    background-color: #a6897e !important;
}

/* Global Styles */
/* Header and Footer */
.rbx-navbar *, .rbx-header {
    color: #a68b7e !important;
    background-color: #f7d0d0 !important;
}

.container-footer, #footer-container * {
    background-color: #a68a7e !important;
    color: white !important;
}

/* Friends Dropdown Menus */
.dropdown-menu, 
.place-container, 
.people-info-card-container .interaction-item, 
#notification-stream-container * {
    background-color: #f7d0d0 !important;
    color: #a68b7e !important;
}

/* Chat */
.chat-body, 
.chat-friend-info *, 
.chat-windows-header, 
.dialogs * {
    background-color: #a68c7e !important;
    color: #f7d0d0 !important;
}

/* Input Fields */
.select-group {
    background-color: #595946 !important;
    border-radius: 10px !important;
}

/* Main Content Background */
body, .content {
    background: transparent !important;
}

.dark-theme, .light-theme, .nav-content {
    width: 100% !important;
    height: 100% !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-image: url("https://i.pinimg.com/1200x/ae/13/b6/ae13b6c374e553564cf59ebdd1542885.jpg") !important;
}
}
